/**
 * Mumbai local knowledge: the irreducible facts every /mumbai/ page is written from.
 *
 * This is the file that stops 2,219 pages reading like one page 2,219 times. Every locality
 * carries its own zone, corridor, railway line, travel reality and school ecosystem, so a
 * writer drafting "IB Maths tutor in Worli" has different true things to say than one
 * drafting "IB Maths tutor in Mulund East".
 *
 * Naming a school is local context only. IB Gram is an independent tutor-matching platform,
 * is not affiliated with, endorsed by or representing any school named here, and anything
 * that renders these names must say so alongside them.
 */

export type MumbaiZoneSlug =
  | "south-mumbai"
  | "western-suburbs"
  | "central-suburbs"
  | "eastern-suburbs"
  | "navi-mumbai"
  | "thane";

export interface MumbaiZone {
  slug: MumbaiZoneSlug;
  name: string;
  /** How a parent here describes where they live. */
  label: string;
  /** The commute/traffic reality that shapes tutor scheduling in this zone. */
  travel: string;
  /** Rail/metro spine families and tutors actually use. */
  transport: string[];
}

