export interface MumbaiLocality {
  slug: string;
  name: string;
  zone: MumbaiZoneSlug;
  /** The corridor, road or node this locality is understood by. */
  corridor: string;
  /** Nearest station or metro stop, as a parent would say it. */
  station: string;
  /** Adjacent areas a tutor would realistically also cover. */
  nearby: string[];
  /** Named residential societies/buildings, where the locality is known for them. */
  societies?: string[];
  /** IB/IGCSE schools whose calendar families here actually live by. */
  schools: string[];
  /** One true, specific thing about studying here. Keeps pages from converging. */
  note: string;
  /** True when the slug names a single society/building rather than a neighbourhood. */
  isSociety?: boolean;
}

